import{_ as a,o,c as t,a0 as n}from"./chunks/framework.OED5XGjC.js";const m=JSON.parse('{"title":"The worktree model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/worktree-model.md","filePath":"explanation/worktree-model.md"}'),r={name:"explanation/worktree-model.md"};function s(c,e,d,i,h,p){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-worktree-model" tabindex="-1">The worktree model <a class="header-anchor" href="#the-worktree-model" aria-label="Permalink to &quot;The worktree model&quot;">​</a></h1><p>Why <code>project/</code> is a git worktree of an orphan branch — and what that buys you.</p><h2 id="the-shape" tabindex="-1">The shape <a class="header-anchor" href="#the-shape" aria-label="Permalink to &quot;The shape&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-repo/</span></span>
<span class="line"><span>├── src/ …            ← code branch (main)</span></span>
<span class="line"><span>├── project/          ← worktree of the orphan \`project\` branch</span></span>
<span class="line"><span>│   ├── TODO.md</span></span>
<span class="line"><span>│   ├── BACKLOG.md</span></span>
<span class="line"><span>│   ├── issues/  proposals/  plans/  adrs/  handoffs/</span></span>
<span class="line"><span>│   ├── index.md</span></span>
<span class="line"><span>│   └── meta.toml</span></span>
<span class="line"><span>└── .gitignore        ← gains \`project/\`</span></span></code></pre></div><p>The <code>project</code> branch shares the repo&#39;s <code>.git</code> object store but has disjoint history — an orphan root, no code ancestors. The worktree mounts it as a plain directory, so tools see ordinary files while <code>git worktree list</code> shows the truth.</p><h2 id="why-an-orphan-branch" tabindex="-1">Why an orphan branch <a class="header-anchor" href="#why-an-orphan-branch" aria-label="Permalink to &quot;Why an orphan branch&quot;">​</a></h2><p>PM state moves at its own cadence. On an orphan branch, ledger commits never touch the code history: no <code>chore: defer T-009</code> noise in <code>main</code>&#39;s log, no PM diffs in PRs, no branch protection friction. <code>project/</code> is gitignored on every code branch — the worktree physically can&#39;t leak into a code commit.</p><h2 id="why-a-worktree-not-just-a-branch" tabindex="-1">Why a worktree (not just a branch) <a class="header-anchor" href="#why-a-worktree-not-just-a-branch" aria-label="Permalink to &quot;Why a worktree (not just a branch)&quot;">​</a></h2><p>The ledger has to be <em>visible</em> — agents edit files, humans read <code>TODO.md</code> — without <code>git checkout</code> swapping the code tree. A worktree keeps both checked out at once.</p><h2 id="commits-are-the-audit-trail" tabindex="-1">Commits are the audit trail <a class="header-anchor" href="#commits-are-the-audit-trail" aria-label="Permalink to &quot;Commits are the audit trail&quot;">​</a></h2><p>Every mutating verb is one atomic, conventional commit on <code>project</code> (<code>chore: add T-012</code>, <code>chore: handoff T-012</code>, <code>chore: resolve I-003</code>, …). So <code>git -C project log</code> <em>is</em> the history of intent — who moved what when, replayable and greppable, with no separate audit store. <code>--no-commit</code> / <code>$MYCO_NO_COMMIT</code> opts out per run; <code>myco commit</code> squashes a batch into one.</p><h2 id="canonical-markdown-disposable-index" tabindex="-1">Canonical markdown, disposable index <a class="header-anchor" href="#canonical-markdown-disposable-index" aria-label="Permalink to &quot;Canonical markdown, disposable index&quot;">​</a></h2><p>The markdown in <code>project/</code> is canonical — human-editable, diffable, frozen by golden fixtures. The redb index (<code>index.redb</code> + <code>repos.toml</code> under <code>$MYCO_HOME</code> → <code>$XDG_DATA_HOME/myco</code> → <code>~/.local/share/myco</code>) is a <em>derived cache</em> that powers <code>status</code>, <code>board</code>, <code>report</code>, and <code>org</code> without re-parsing files. Delete it and <code>myco index rebuild</code> derives it back; <code>myco check</code> finds and repairs drift between the two.</p><p>See <a href="./file-spec.html">the file spec</a> for what the files contain and <a href="./architecture.html">architecture</a> for the crates that implement it.</p>`,14)])])}const b=a(r,[["render",s]]);export{m as __pageData,b as default};
